function modReset(){
modDuration = "--:--"
modCursor = 0
modSeconds = 0
modMissing = 0
modPass = 0
modFinished = false
modSupported = true
}
function modParseTime(value){
var parts = String(value).split(":")
if(parts.length < 2 || parts.length > 3)return -1
var seconds = 0
for(var i = 0;i < parts.length;i++){
if(!parts[i].length)return -1
var number = Number(parts[i])
if(!isFinite(number)|| number < 0 || Math.floor(number)!== number)return -1
if(i > 0 && number >= 60)return -1
seconds = seconds * 60 + number
}
return seconds
}
function modFormatTime(seconds){
function pad(number){return number < 10 ? "0" + number:String(number)}
if(seconds >= 3600)
return Math.floor(seconds / 3600)+ ":" + pad(Math.floor(seconds / 60)% 60)+ ":" + pad(seconds % 60)
return Math.floor(seconds / 60)+ ":" + pad(seconds % 60)
}
function modStep(){
try{
var count = modRows.count
if(!list || count <= 0)return
var end = Math.min(count,modCursor + 8)
for(;modCursor < end;modCursor++){
var row = modRows.items.get(modCursor).model
var seconds = modParseTime(row.TrackDurationUint32Role)
if(seconds < 0)modMissing++
else modSeconds += seconds
}
if(modCursor < count)return
if(modMissing === 0){
modDuration = modFormatTime(modSeconds)
modFinished = true
}else if(++modPass >= 20){
modFinished = true
}else{
modCursor = 0
modSeconds = 0
modMissing = 0
}
}catch(error){
modSupported = false
console.log("AM",error)
}
}
function modPlayAlbum(){
if(!modAlbum || !list || listView.count <= 0)return
try{
var name = String(modRows.items.get(0).model.NameQstringRole)
touchListAt(0,name)
}catch(error){
console.log("AM",error)
}
}
